# ── Duplicate Tracking ────────────────────────────────────────────────────────
# Persistent TSV: domain \t date \t availability \t score \t verdict \t action_taken

def load_duplicates() -> dict:
    """Return {domain: {date, availability, score, verdict, action_taken}}."""
    dupes = {}
    if not os.path.isfile(DUPES_PATH):
        return dupes
    try:
        with open(DUPES_PATH, "r") as f:
            header = f.readline()  # skip header
            for line in f:
                parts = line.strip().split("\t")
                if len(parts) >= 6:
                    domain = parts[0]
                    dupes[domain] = {
                        "date": parts[1],
                        "availability": parts[2],
                        "score": parts[3],
                        "verdict": parts[4],
                        "action_taken": parts[5],
                    }
        log.info(f"Duplicate tracking: loaded {len(dupes)} previously evaluated domains")
    except Exception as e:
        log.warning(f"Could not load duplicates: {e}")
    return dupes


def save_duplicates(dupes: dict):
    """Write the duplicates dict to the TSV file."""
    try:
        with open(DUPES_PATH, "w") as f:
            f.write("domain\tdate\tavailability\tscore\tverdict\taction_taken\n")
            for domain, info in sorted(dupes.items()):
                f.write(
                    f"{domain}\t{info['date']}\t{info['availability']}\t"
                    f"{info['score']}\t{info['verdict']}\t{info['action_taken']}\n"
                )
        log.info(f"Duplicate tracking: saved {len(dupes)} entries to {DUPES_PATH}")
    except Exception as e:
        log.warning(f"Could not save duplicates: {e}")


def mark_evaluated(dupes: dict, domain: str, availability: str, score: int,
                   verdict: str, action_taken: str, today: str = None):
    """Record a domain as evaluated in the duplicates dict."""
    if today is None:
        today = date.today().isoformat()
    dupes[domain] = {
        "date": today,
        "availability": availability,
        "score": str(score),
        "verdict": verdict,
        "action_taken": action_taken,
    }


# ── JSON Output Builder ───────────────────────────────────────────────────────

def build_json_output(final: list, total_candidates: int, today: str = None) -> dict:
    """Build the JSON output matching the domain_acquisition trigger schema."""
    if today is None:
        today = date.today().isoformat()
    results = []
    for d in final:
        dom = d["domain"]
        tld = dom[dom.rfind("."):]
        results.append({
            "domain": dom,
            "availability": d.get("availability", "unknown"),
            "score": d.get("score", 0),
            "service_score": d.get("service_score", 0),
            "verdict": d.get("verdict", ""),
            "factors": d.get("factors", {}),
            "price": tld_price(tld),
            "registrar": TLD_REGISTRAR.get(tld, "Namecheap"),
            "wayback_history": d.get("factors", {}).get("has_history", False),
        })
    return {
        "date": today,
        "total_domains": total_candidates,
        "available": sum(1 for d in final if d.get("availability") == "available"),
        "results": results,
    }


def write_json(data: dict, output_path: str):
    """Write JSON output to a file."""
    os.makedirs(os.path.dirname(output_path), exist_ok=True)
    with open(output_path, "w") as f:
        json.dump(data, f, indent=2)
    log.info(f"JSON output written: {output_path}")
    # Always write to latest.json in memory dir as well (for pipeline compatibility)
    latest = os.path.join(MEMORY_DIR, "latest.json")
    if os.path.abspath(output_path) != os.path.abspath(latest):
        with open(latest, "w") as f:
            json.dump(data, f, indent=2)
        log.info(f"JSON output also mirrored to: {latest}")


# ── Portfolio Tracker ─────────────────────────────────────────────────────────

def load_portfolio() -> list:
    """Load portfolio.tsv with acquired/registered domains."""
    path = os.path.join(MEMORY_DIR, "portfolio.tsv")
    portfolio = []
    if os.path.isfile(path):
        try:
            with open(path, "r") as f:
                header = f.readline()
                for line in f:
                    parts = line.strip().split("\t")
                    if len(parts) >= 4:
                        portfolio.append({
                            "domain": parts[0],
                            "date_acquired": parts[1],
                            "registrar": parts[2],
                            "notes": parts[3] if len(parts) > 3 else "",
                        })
            log.info(f"Portfolio tracker: loaded {len(portfolio)} domains")
        except Exception as e:
            log.warning(f"Could not load portfolio: {e}")
    return portfolio


def add_to_portfolio(domain: str, date_acquired: str = None, registrar: str = "", notes: str = ""):
    """Add a domain to the portfolio tracker."""
    if date_acquired is None:
        date_acquired = date.today().isoformat()
    path = os.path.join(MEMORY_DIR, "portfolio.tsv")
    write_header = not os.path.isfile(path)
    with open(path, "a") as f:
        if write_header:
            f.write("domain\tdate_acquired\tregistrar\tnotes\n")
        f.write(f"{domain}\t{date_acquired}\t{registrar}\t{notes}\n")
    log.info(f"Portfolio tracker: added {domain}")
    return path


def save_portfolio_tsv(portfolio: list, path: str = None):
    """Save the entire portfolio list."""
    if path is None:
        path = os.path.join(MEMORY_DIR, "portfolio.tsv")
    with open(path, "w") as f:
        f.write("domain\tdate_acquired\tregistrar\tnotes\n")
        for entry in portfolio:
            f.write(
                f"{entry['domain']}\t{entry.get('date_acquired', '')}\t"
                f"{entry.get('registrar', '')}\t{entry.get('notes', '')}\n"
            )
    log.info(f"Portfolio tracker: saved {len(portfolio)} entries")


